function generateCharacter(fail=false){const c=state.characterImage;if(characterBusy())return;if(!c.prompt.trim()){toast('请先输入形象描述','warning');return;}const token=++characterOperation;c.status='generating';c.error='';render();setTimeout(()=>{if(token!==characterOperation)return;if(fail){c.status='error';c.error='模拟生成失败，请点击重试生成';}else{c.sourceType='ai';c.activeView='front';c.views={};for(const view of Object.keys(characterViewLabels)){const image=characterPortrait(view);c.views[view]={image,source:image,selection:[],history:[],editPrompt:''};}c.image=c.views.front.image;c.source=c.image;c.history=[];c.selection=[];c.editPrompt='';c.cutoutConfirmed=true;c.multiViewStatus='ready';c.confirmed=false;c.creationMode=null;c.status='ready';if(c===state.characterImage)invalidateCharacter();}persist();render();},1200);}
function editCharacter(description=state.characterImage.editPrompt){const c=state.characterImage;if(characterBusy()||!c.image||!c.selection.length)return;if(!description?.trim()){toast('请描述如何修改圈选区域','warning');return;}c.editPrompt=description.trim();const token=++characterOperation,region=structuredClone(c.selection),edit=description.trim();c.status='editing';render();setTimeout(async()=>{if(token!==characterOperation||c!==state.characterImage)return;try{const h={id:'edit-'+Date.now(),region,description:edit,time:new Date().toLocaleTimeString('zh-CN',{hour12:false}),color:/棕|brown/i.test(edit)?'#55392d':/红/.test(edit)?'#ba6262':/蓝/.test(edit)?'#477dba':/绿/.test(edit)?'#528d70':'#b19778'};c.history.push(h);await rebuildCharacter(c);if(token!==characterOperation||c!==state.characterImage)return;c.selection=[];c.editPrompt='';state.chat.drafts[4]='';c.status='ready';invalidateCharacter();persist();render();}catch{c.status='error';c.error='局部修改失败，请重试';render();}},1000);}
async function rebuildCharacter(c){const image=new Image();image.src=c.source;await image.decode();const canvas=document.createElement('canvas');canvas.width=image.naturalWidth;canvas.height=image.naturalHeight;const ctx=canvas.getContext('2d');ctx.drawImage(image,0,0);for(const h of c.history){ctx.save();const mask=document.createElement('canvas');mask.width=canvas.width;mask.height=canvas.height;const m=mask.getContext('2d');m.strokeStyle=h.color;m.fillStyle=h.color;m.lineCap='round';m.lineJoin='round';for(const stroke of h.region){m.lineWidth=stroke.size*canvas.width;m.beginPath();stroke.points.forEach((p,i)=>i?m.lineTo(p.x*canvas.width,p.y*canvas.height):m.moveTo(p.x*canvas.width,p.y*canvas.height));m.stroke();const p=stroke.points[0];m.beginPath();m.arc(p.x*canvas.width,p.y*canvas.height,m.lineWidth/2,0,Math.PI*2);m.fill();}ctx.globalAlpha=.5;ctx.globalCompositeOperation='multiply';ctx.drawImage(mask,0,0);ctx.restore();}c.image=canvas.toDataURL('image/png');ensureCharacterViews(c);c.views[c.activeView]=viewSnapshot(c);}
function invalidateAudioCheck(kind='all'){state.qaConfirmed=false;state.audio.declarationConfirmed=false;state.exportDone=false;if(kind==='all'||kind==='voice'||kind==='music'||kind==='duration')state.audio.syncStatus='pending';if(kind==='all'||kind==='caption')state.audio.captionCheck='pending';}
