function captionWindow(scene,segment){const start=state.scenes.slice(0,state.scenes.indexOf(scene)).reduce((sum,s)=>sum+Number(s.duration||0),0);const duration=Math.max(.1,Number(scene.duration)||5);const localStart=clamp(segment.startOffset,0,duration);const localEnd=clamp(segment.endOffset,duration===localStart?localStart:localStart+.1,duration);return {start:Number((start+localStart).toFixed(1)),end:Number((start+localEnd).toFixed(1)),sceneStart:start,sceneEnd:start+duration};}
