function addScene(){const n=state.scenes.length+1,s=makeScene(n,`新分镜 ${n}`,'描述这个片段中发生的动作、场景和情绪。',5);s.id=`scene-${Date.now()}`;s.captionSegments[0].id=`${s.id}-caption-1`;state.scenes.push(s);state.positions[s.id]={x:250+(n-1)*225,y:120};state.selected=s.id;state.selectedType='scene';state.selectedCaptionId=s.captionSegments[0].id;state.addMenuOpen=false;state.mobileProps=window.innerWidth<=760;invalidateAudioCheck('all');persist();render();toast('已添加分镜，并自动关联字幕模块','success');}
function addCaptionSegment(){const s=selectedScene();if(!s)return;s.captionSegments??=[];if(!s.captionEnabled&&s.captionSegments.length){s.captionEnabled=true;state.selected=s.id;state.selectedType='caption';state.selectedCaptionId=s.captionSegments[0].id;state.addMenuOpen=false;invalidateAudioCheck('caption');persist();render();toast(`已恢复「${s.title}」的字幕模块`,'success');return;}s.captionEnabled=true;const duration=Math.max(.1,Number(s.duration)||5);const lastEnd=s.captionSegments.reduce((max,segment)=>Math.max(max,Number(segment.endOffset)||0),0);const start=Math.min(Math.max(0,lastEnd),Math.max(0,duration-.1));const segment={id:`caption-${Date.now()}`,text:'输入新的屏幕字幕',startOffset:Number(start.toFixed(1)),endOffset:Number(Math.min(duration,start+Math.max(.1,duration/2)).toFixed(1))};s.captionSegments.push(segment);state.selected=s.id;state.selectedType='caption';state.selectedCaptionId=segment.id;state.addMenuOpen=false;markVoiceStale(s);invalidateAudioCheck('caption');persist();render();toast(`已为「${s.title}」添加字幕段`,'success');}
