function updateCaptionTime(input){const scene=state.scenes.find(s=>s.id===input.dataset.captionScene),segment=scene?.captionSegments?.find(item=>item.id===input.dataset.captionId);if(!scene||!segment)return;const index=state.scenes.indexOf(scene),sceneStart=state.scenes.slice(0,index).reduce((n,s)=>n+Number(s.duration||0),0),duration=Math.max(.1,Number(scene.duration)||5),currentStart=clamp(segment.startOffset,0,duration-.1),currentEnd=clamp(segment.endOffset,currentStart+.1,duration),absolute=Number(input.value);let start=currentStart,end=currentEnd;if(input.dataset.captionTime==='start'){start=clamp(absolute-sceneStart,0,duration-.1);if(end<start+.1)end=Math.min(duration,start+.1)}else{end=clamp(absolute-sceneStart,start+.1,duration);if(end<=start)start=Math.max(0,end-.1)}segment.startOffset=Number(start.toFixed(1));segment.endOffset=Number(end.toFixed(1));state.selected=scene.id;state.selectedType='caption';state.selectedCaptionId=segment.id;markVoiceStale(scene);invalidateAudioCheck('caption');scheduleSave();}
