  const portEl=e.target.closest('[data-port]');if(portEl&&state.connectMode){if(suppressPortClick){suppressPortClick=false;return}if(!connectStart){connectStart=portEl.dataset.id;toast('已选择来源，请点击或拖动到目标输入点')}else if(connectStart!==portEl.dataset.id){const normalized=`${connectStart}:${portEl.dataset.id}`;if(!state.links.includes(normalized))state.links.push(normalized);connectStart=null;persist();render();toast('片段关联已建立','success')}return;}
