app.addEventListener('input',e=>{
  const t=e.target;
  if(t.dataset.feedbackDraft!==undefined){state.feedback.draft=t.value;const button=document.querySelector('[data-action="add-feedback-comment"]');if(button)button.disabled=!t.value.trim();scheduleSave();return;}
  if(t.dataset.feedbackEditDraft!==undefined){state.feedback.editDraft=t.value;scheduleSave();return;}
  if(t.dataset.feedbackReply){const comment=state.feedback.comments.find(item=>item.id===t.dataset.feedbackReply);if(comment){comment.reply=t.value;const button=t.parentElement.querySelector('[data-action="resolve-feedback"]');if(button)button.disabled=!t.value.trim();scheduleSave();}return;}
  if(t.dataset.veevaField){state.veevaForm[t.dataset.veevaField]=t.value;scheduleSave();return;}
  if(t.dataset.veevaNote){state.veevaNotes[t.dataset.veevaNote]=t.value;scheduleSave();return;}
  if(t.dataset.creativeField){updateCreativeField(t);return;}
  if(t.dataset.chatDraft){const step=Number(t.dataset.chatDraft);state.chat.drafts[step]=t.value;if(step===4&&state.characterImage.selection.length)state.characterImage.editPrompt=t.value;const send=t.closest('.chat-composer')?.querySelector('.chat-send');if(send)send.disabled=!t.value.trim()||!!state.chat.busy;scheduleSave();return;}
  if(t.dataset.mainKv){state.mainKv[t.dataset.mainKv]=t.value;invalidateMainKv();scheduleSave();return;}
  if(t.dataset.characterImage){const key=t.dataset.characterImage;state.characterImage[key]=key==='brushSize'?Math.max(6,Math.min(80,Number(t.value)||28)):t.value;if(key==='brushSize')document.getElementById('brush-value').textContent=state.characterImage.brushSize+'px';if(key==='editPrompt'){state.chat.drafts[4]=t.value;const chat=document.querySelector('[data-chat-draft="4"]');if(chat)chat.value=t.value;const send=chat?.closest('.chat-composer')?.querySelector('.chat-send');if(send)send.disabled=!t.value.trim();}scheduleSave();return;}
  if(t.dataset.sceneCaption){
    const scene=state.scenes.find(s=>s.id===t.dataset.sceneCaption);
    if(scene){
      scene.captionEnabled=true;
      scene.caption=t.value;
      if(scene.captionSegments?.[0])scene.captionSegments[0].text=t.value;
      else{
        scene.captionSegments=[{id:`${scene.id}-caption-${Date.now()}`,text:t.value,startOffset:0,endOffset:Number(scene.duration)||5}];
        state.selectedCaptionId=scene.captionSegments[0].id;
      }
      markVoiceStale(scene);
      invalidateAudioCheck('caption');
      scheduleSave();
    }
    return;
  }
  if(t.dataset.captionSegment){
    const scene=state.scenes.find(s=>s.id===t.dataset.captionScene);
    const segment=scene?.captionSegments?.find(item=>item.id===t.dataset.captionSegment);
    if(scene&&segment){
      segment.text=t.value;
      if(scene.captionSegments[0]?.id===segment.id)scene.caption=t.value;
      state.selected=scene.id;
      state.selectedType='caption';
      state.selectedCaptionId=segment.id;
      markVoiceStale(scene);
      invalidateAudioCheck('caption');
      const copy=document.querySelector(`.caption-node[data-scene-id="${scene.id}"] .node-copy`);
      if(copy)copy.textContent=scene.captionSegments.map(item=>item.text?.trim()).filter(Boolean).join(' / ')||'点击添加屏幕字幕';
      const status=document.querySelector(`.voice-node[data-scene-id="${scene.id}"] [data-role="voice-status"]`);
      if(status){
        status.textContent=scene.voiceStatus;
        status.classList.toggle('node-warning',scene.voiceStatus==='需重新生成');
        status.classList.toggle('node-enabled',scene.voiceGenerated);
        status.classList.toggle('node-disabled',!scene.voiceGenerated&&scene.voiceStatus!=='需重新生成');
      }
      scheduleSave();
    }
    return;
  }
  if(t.dataset.captionTime){updateCaptionTime(t);return}
  if(t.name==='brief'){state.brief=t.value;scheduleSave();return}
  if(t.name&&Object.hasOwn(state.form,t.name)){state.form[t.name]=t.value;scheduleSave();return}
  if(t.dataset.scene){const s=selectedScene();if(!s)return;const key=t.dataset.scene;s[key]=t.value;if(key==='narration')invalidateAudioCheck('voice');else if(key==='voice'||key==='voiceStyle'){markVoiceStale(s);invalidateAudioCheck('voice')}else if(key==='caption'){if(s.captionSegments?.[0])s.captionSegments[0].text=t.value;markVoiceStale(s);invalidateAudioCheck('caption')}else{if(key==='prompt')s.description=t.value;s.generated=false;s.status='待生成';invalidateAudioCheck('all')}scheduleSave();return}
  if(t.dataset.audio==='volume'){state.audio.volume=Number(t.value);const value=t.parentElement.querySelector('b');if(value)value.textContent=`${t.value}%`;scheduleSave();return}
  if(t.dataset.character){state.character[t.dataset.character]=t.value;scheduleSave()}
});
app.addEventListener('change',e=>{
  const t=e.target;
  if(t.dataset.accountSwitch!==undefined){state.currentUser=t.value==='manager'?'manager':'creator';if(state.currentUser==='manager'&&state.feedback.status!=='draft'){state.step=8;state.maxStep=Math.max(state.maxStep,8)}persist();render();toast(`已切换至${state.currentUser==='manager'?'小王':'小李'}账号`,'success');return;}
  if(t.dataset.feedbackTarget!==undefined){state.feedback.target=t.value;scheduleSave();return;}
  if(t.dataset.veevaField){state.veevaForm[t.dataset.veevaField]=t.value;scheduleSave();return;}
  if(t.dataset.veevaStatus){state.veevaStatus[t.dataset.veevaStatus]=t.value;scheduleSave();return;}
  if(t.name==='export-quality'){state.exportQuality=t.value;scheduleSave();return;}
  if(t.id==='main-kv-reference-upload'){const file=t.files?.[0],kv=state.mainKv;if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>6*1024*1024){toast('请选择 6MB 以内的 PNG、JPEG 或 WebP 参考图','warning');t.value='';return}const reader=new FileReader();reader.onload=()=>{kv.referenceImage=String(reader.result);kv.referenceName=file.name;invalidateMainKv();persist();render();toast('参考图已添加，生成时将参考其构图、色调和视觉氛围','success')};reader.onerror=()=>toast('参考图读取失败，请重新上传','warning');reader.readAsDataURL(file);return;}
  if(t.id==='main-kv-upload'){const file=t.files?.[0],kv=state.mainKv;if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>6*1024*1024){toast('请选择 6MB 以内的 PNG、JPEG 或 WebP 图片','warning');t.value='';return}const reader=new FileReader();kv.status='uploading';invalidateMainKv();reader.onload=()=>{kv.image=String(reader.result);kv.status='ready';persist();render();toast('背景参考图已上传，请确认后继续','success')};reader.onerror=()=>{kv.status='error';kv.error='文件读取失败，请重新上传';render()};reader.readAsDataURL(file);return;}
  if(t.id==='character-upload'){const file=t.files?.[0],c=state.characterImage;if(!file||characterBusy())return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>4*1024*1024){toast('请选择 4MB 以内的 PNG、JPEG 或 WebP 图片','warning');t.value='';return;}const token=++characterOperation,reader=new FileReader();c.status='uploading';render();reader.onload=()=>{const img=new Image();img.onload=()=>{if(token!==characterOperation||c!==state.characterImage)return;c.image=String(reader.result);c.source=c.image;c.uploadOriginal=c.image;c.sourceType='upload';c.activeView='front';c.views={front:{image:c.image,source:c.image,selection:[],history:[],editPrompt:''}};c.cutoutStatus='idle';c.cutoutConfirmed=false;c.multiViewStatus='idle';c.history=[];c.selection=[];c.editPrompt='';c.creationMode=null;c.status='ready';c.error='';invalidateCharacter();persist();render();};img.onerror=()=>{if(c!==state.characterImage)return;c.status='error';c.error='无法读取图片，请重新上传';render();};img.src=String(reader.result);};reader.onerror=()=>{if(c!==state.characterImage)return;c.status='error';c.error='文件读取失败，请重新上传';render();};reader.readAsDataURL(file);return;}
  if(t.dataset.captionTime){updateCaptionTime(t);render();return}
  if(t.name==='brief'){state.brief=t.value;scheduleSave();return}
  if(t.name&&Object.hasOwn(state.form,t.name)){state.form[t.name]=t.value;if(t.name==='goal'){state.mainKv={...freshMainKv(),mode:state.mainKv.mode};persist();render();return}if(t.name==='template'){state.form.template=t.value;document.querySelectorAll('.choice').forEach(x=>x.classList.toggle('selected',x.querySelector('input')?.checked))}scheduleSave();return}
  if(t.dataset.audio){state.audio[t.dataset.audio]=t.value;if(t.dataset.audio==='music')invalidateAudioCheck('music');if(t.dataset.audio==='captionStyle')invalidateAudioCheck('caption');persist();render();return}
  if(t.dataset.scene){const s=selectedScene();if(s){const key=t.dataset.scene;s[key]=key==='duration'?Math.max(.1,Number(t.value)||.1):t.value;if(key==='duration'){const duration=s.duration;s.captionSegments?.forEach(segment=>{segment.startOffset=Number(clamp(segment.startOffset,0,Math.max(0,duration-.1)).toFixed(1));segment.endOffset=Number(clamp(segment.endOffset,segment.startOffset+.1,duration).toFixed(1))});markVoiceStale(s);invalidateAudioCheck('duration')}else if(key==='narration')invalidateAudioCheck('voice');else if(key==='voice'||key==='voiceStyle'){markVoiceStale(s);invalidateAudioCheck('voice')}else if(key==='caption'){if(s.captionSegments?.[0])s.captionSegments[0].text=t.value;markVoiceStale(s);invalidateAudioCheck('caption')}else{if(key==='prompt')s.description=t.value;s.generated=false;s.status='待生成';invalidateAudioCheck('all')}persist();render()}return}
  if(t.dataset.character){state.character[t.dataset.character]=t.value;invalidateAudioCheck('all');render()}
});

app.addEventListener('pointerdown',e=>{const p=e.target.closest('[data-port]');if(p&&state.connectMode){if(!connectStart)connectStart=p.dataset.id;e.preventDefault();return}const node=e.target.closest('.node:not(.graph-child)');if(node){const id=node.dataset.node;dragging={id,startX:e.clientX,startY:e.clientY,orig:{...(state.positions[id]||{x:250,y:120})}};dragMoved=false;node.setPointerCapture?.(e.pointerId);return}const stage=e.target.closest('#canvas-stage');if(stage&&e.target===stage){panStart={x:e.clientX,y:e.clientY,orig:{...state.pan}};stage.classList.add('panning')}});
window.addEventListener('pointermove',e=>{if(dragging){const dx=(e.clientX-dragging.startX)/state.zoom,dy=(e.clientY-dragging.startY)/state.zoom;if(Math.abs(dx)+Math.abs(dy)>5)dragMoved=true;state.positions[dragging.id]={x:Math.max(0,dragging.orig.x+dx),y:Math.max(0,dragging.orig.y+dy)};const el=document.querySelector(`[data-node="${dragging.id}"]`);if(el){el.style.left=state.positions[dragging.id].x+'px';el.style.top=state.positions[dragging.id].y+'px'}if(dragging.id!=='character'){const caption=document.querySelector(`.caption-node[data-parent="${dragging.id}"]`),voice=document.querySelector(`.voice-node[data-parent="${dragging.id}"]`);if(caption){caption.style.left=state.positions[dragging.id].x+'px';caption.style.top=state.positions[dragging.id].y+224+'px'}if(voice){voice.style.left=state.positions[dragging.id].x+'px';voice.style.top=state.positions[dragging.id].y+354+'px'}}const svg=document.querySelector('.connections');if(svg)svg.innerHTML=buildConnections()}else if(panStart){state.pan={x:panStart.orig.x+e.clientX-panStart.x,y:panStart.orig.y+e.clientY-panStart.y};const content=document.getElementById('canvas-content');if(content)content.style.transform=`translate(${state.pan.x}px,${state.pan.y}px) scale(${state.zoom})`}}, {passive:true});
window.addEventListener('pointerup',e=>{if(dragging){dragging=null;if(dragMoved){persist();setTimeout(()=>{dragMoved=false},80)}}if(panStart){panStart=null;document.querySelector('#canvas-stage')?.classList.remove('panning');persist()}if(connectStart&&state.connectMode){const target=e.target.closest?.('[data-port]');if(target&&target.dataset.id!==connectStart){const link=`${connectStart}:${target.dataset.id}`;if(!state.links.includes(link))state.links.push(link);connectStart=null;suppressPortClick=true;persist();render();toast('片段关联已建立','success')}else if(!target){connectStart=null}}});
window.addEventListener('keydown',e=>{if(e.key==='Escape'){closeScenePreview();document.querySelector('.keyframe-backdrop')?.remove();document.querySelector('.modal-backdrop')?.remove();state.connectMode=false;connectStart=null;render()}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='s'){e.preventDefault();persist();toast('项目已保存','success')}});
window.addEventListener('resize',()=>{if(window.innerWidth>760&&state.mobileProps){state.mobileProps=false;render()}});
