const kvTemplates={品牌认知:[['brand-spring','春日守护'],['brand-trust','可信相伴']],产品介绍:[['product-focus','产品聚焦'],['product-life','融入日常']],健康科普:[['health-guide','健康指南'],['health-nature','自然健康']],社媒传播:[['social-energy','社媒活力'],['social-story','故事瞬间']],员工沟通:[['people-together','同心同行'],['people-future','共创未来']]};
function mainKvArtwork(label,tone='#1971b8'){const canvas=document.createElement('canvas');canvas.width=1200;canvas.height=675;const x=canvas.getContext('2d'),g=x.createLinearGradient(0,0,1200,675);g.addColorStop(0,'#e9f7f0');g.addColorStop(.56,'#d9eef8');g.addColorStop(1,tone);x.fillStyle=g;x.fillRect(0,0,1200,675);x.fillStyle='#ffffff35';for(let i=0;i<7;i++){x.beginPath();x.arc(890+i*70,80+i%2*110,120-i*8,0,Math.PI*2);x.fill()}x.fillStyle='#fff';x.font='700 58px sans-serif';x.fillText(label.slice(0,18),72,470);x.font='28px sans-serif';x.fillText('Bayer · Science for a better life',72,525);return canvas.toDataURL('image/jpeg',.88)}
function sceneKeyframe(scene){const signature=JSON.stringify([scene.prompt||scene.description,scene.style,state.form.ratio,usesMainCharacter(),usesMainCharacter()?(state.characterImages||[]).filter(asset=>asset.imageState?.confirmed).map(asset=>[asset.id,asset.imageState.image]):state.mainKv.image]);if(!scene.keyframe||scene.keyframe.signature!==signature){scene.keyframe={image:mainKvArtwork(scene.title,['#1971b8','#168b75','#65894e','#95749c'][Math.max(0,state.scenes.indexOf(scene))%4]),signature,confirmed:false};scene.generated=false;if(scene.status!=='生成中')scene.status='待确认关键帧';}return scene.keyframe;}
function keyframeProperties(scene){const frame=sceneKeyframe(scene);return `<section class="keyframe-properties"><button class="prop-preview keyframe-preview" data-action="preview-keyframe" data-id="${esc(scene.id)}" title="放大查看关键帧"><img src="${esc(frame.image)}" alt="${esc(scene.title)}关键帧"><span class="pill pill-blue">放大查看关键帧</span></button><div class="keyframe-confirm"><span class="pill ${frame.confirmed?'pill-green':'pill-amber'}">${frame.confirmed?'已确认':'待确认关键帧'}</span><button class="btn btn-primary btn-sm" data-action="confirm-keyframe" data-id="${esc(scene.id)}" ${frame.confirmed?'disabled':''}>确认关键帧</button></div></section>`;}
function showKeyframe(id){const scene=state.scenes.find(item=>item.id===id);if(!scene)return;document.querySelector('.keyframe-backdrop')?.remove();const frame=sceneKeyframe(scene),wrap=document.createElement('div');wrap.className='scene-preview-backdrop keyframe-backdrop';wrap.innerHTML=`<section class="scene-preview-modal keyframe-modal" role="dialog" aria-modal="true" aria-label="关键帧预览"><header><div><span>关键帧预览</span><b>${esc(scene.title)}</b></div><button class="modal-close" data-action="close-keyframe" aria-label="关闭预览">×</button></header><img class="keyframe-full" src="${esc(frame.image)}" alt="${esc(scene.title)}关键帧"><footer><span class="pill ${frame.confirmed?'pill-green':'pill-amber'}">${frame.confirmed?'已确认':'确认后可生成视频'}</span><button class="btn btn-primary" data-action="confirm-keyframe" data-id="${esc(scene.id)}" ${frame.confirmed?'disabled':''}>确认关键帧</button></footer></section>`;wrap.addEventListener('click',event=>{if(event.target===wrap)wrap.remove();});document.body.appendChild(wrap);wrap.querySelector('.modal-close')?.focus();persist();}
function invalidateMainKv(){state.mainKv.confirmed=false;state.mainKv.error='';}
function guardedGoto(step){if(step>=5&&!usesMainCharacter()&&!state.mainKv.confirmed){toast('请先确认背景参考图','warning');step=4;}goto(step)}
function projectForm(){const kv=state.mainKv={...freshMainKv(),...(state.mainKv||{})},templates=kvTemplates[state.form.goal]||kvTemplates['品牌认知'],busy=kv.status==='generating';return `${heading('STEP 02 · PROJECT','创建视频项目','定义活动目标并确认主 KV，AI 将以此作为后续创意与画面的视觉依据。')}<div class="project-chat-layout"><section class="card form-card project-workspace"><div class="form-grid"><div class="field full"><label>项目名称</label><input class="input" name="name" value="${esc(state.form.name)}" placeholder="给项目起个名字"></div><div class="field"><label>活动目标</label><select class="select" name="goal">${Object.keys(kvTemplates).map(o=>`<option ${state.form.goal===o?'selected':''}>${o}</option>`).join('')}</select></div><div class="field"><label>目标受众</label><input class="input" name="audience" value="${esc(state.form.audience)}" placeholder="例如：关注健康的年轻家庭"></div><div class="field"><label>视频语言</label><select class="select" name="language">${['简体中文','English','中英双语'].map(o=>`<option ${state.form.language===o?'selected':''}>${o}</option>`).join('')}</select></div><div class="field"><label>画面比例</label><div class="aspect-buttons">${[['9:16','竖屏'],['16:9','横屏'],['1:1','方形']].map(([v,l])=>`<button class="aspect-btn ${state.form.ratio===v?'selected':''}" data-action="set-ratio" data-value="${v}">${l}<br><span class="tiny">${v}</span></button>`).join('')}</div></div><div class="field"><label>视频时长</label><select class="select" name="duration">${[10,15,20,30,45,60].map(v=>`<option value="${v}" ${Number(state.form.duration)===v?'selected':''}>约 ${v} 秒</option>`).join('')}</select></div><div class="field full"><label>主 KV</label><div class="kv-mode-tabs">${[['bayer','使用 Bayer 模版'],['ai','AI 生成'],['upload','手动上传']].map(([v,l])=>`<button class="kv-mode ${kv.mode===v?'selected':''}" data-action="set-kv-mode" data-value="${v}">${l}</button>`).join('')}</div><div class="kv-workspace">${kv.mode==='bayer'?`<div class="kv-template-head"><b>适用于「${esc(state.form.goal)}」的 Bayer 模版</b><span>活动目标变化后自动更新</span></div><div class="kv-template-grid">${templates.map(([id,name],i)=>`<button class="kv-template ${kv.templateId===id?'selected':''}" data-action="select-kv-template" data-id="${esc(id)}" data-name="${esc(name)}" data-tone="${i?'#169985':'#1971b8'}"><span class="kv-template-art tone-${i+1}"><i>BAYER</i></span><b>${esc(name)}</b><small>${i?'人物叙事 · 品牌绿':'明亮构图 · 品牌蓝'}</small></button>`).join('')}</div>`:kv.mode==='ai'?`<div class="field"><label>描述想要呈现的主 KV 效果</label><textarea class="textarea" data-main-kv="prompt" placeholder="例如：春日清晨，一家人在公园中自然互动，明亮真实的品牌广告风格" ${busy?'disabled':''}>${esc(kv.prompt)}</textarea></div><button class="btn btn-primary btn-sm" data-action="generate-main-kv" ${busy?'disabled':''}>${busy?'<span class="spinner"></span> AI 正在生成':'✦ 生成 KV'}</button>`:`<div class="field"><label for="main-kv-upload">上传主 KV 图片</label><input id="main-kv-upload" type="file" accept="image/png,image/jpeg,image/webp"><span class="field-hint">支持 PNG / JPEG / WebP，最大 6MB</span></div>`}<div class="kv-preview ${kv.image?'ready':''}">${kv.image?`<img src="${esc(kv.image)}" alt="主 KV 预览">`:'<div><b>主 KV 预览</b><span>选择模版、生成或上传后将在这里显示</span></div>'}${busy?'<div class="kv-generating"><span class="spinner"></span>正在生成主 KV…</div>':''}</div>${kv.error?`<p class="character-error" role="alert">${esc(kv.error)}</p>`:''}<div class="kv-confirm-row"><span class="pill ${kv.confirmed?'pill-green':'pill-amber'}">${kv.confirmed?'✓ 主 KV 已确认':'待确认'}</span><button class="btn btn-soft btn-sm" data-action="confirm-main-kv" ${!kv.image||busy||kv.confirmed?'disabled':''}>确认主 KV</button></div></div></div></div><div class="page-actions"><button class="btn btn-quiet" data-action="back-home">← 返回工作台</button><button class="btn btn-primary" data-action="start-creative" ${!kv.confirmed?'disabled':''}>下一步：生成创意 →</button></div></section><aside class="chat-column">${chatbot(2)}</aside></div>`}
const projectFormBase=projectForm;projectForm=function(){const kv=state.mainKv,characterChoice=`<div class="field full character-use-field"><label>视频是否引用主人物形象</label><div class="character-use-options"><button class="character-use-option ${usesMainCharacter()?'selected':''}" data-action="set-character-use" data-value="yes"><b>是，使用主人物形象</b><span>确认脚本后生成主形象，并在画布中关联分镜</span></button><button class="character-use-option ${usesMainCharacter()?'':'selected'}" data-action="set-character-use" data-value="no"><b>否，不使用主人物形象</b><span>跳过形象生成，画布仅编排分镜、字幕与声音</span></button></div><p class="field-hint">${['品牌认知','社媒传播'].includes(state.form.goal)?'根据当前活动目标，建议使用主人物形象。':'根据当前活动目标，可不使用主人物形象。'} 最终以你的选择为准。</p></div>`,reference=`<div class="kv-reference"><div class="kv-reference-head"><div><b>参考 KV</b><span>可选 · 用于参考构图、色调和视觉氛围，不会完整复刻</span></div>${kv.referenceImage?'<button class="text-link" data-action="remove-kv-reference">移除</button>':''}</div>${kv.referenceImage?`<label class="kv-reference-ready"><img src="${esc(kv.referenceImage)}" alt="参考 KV"><span><b>${esc(kv.referenceName||'参考图片')}</b><small>点击更换参考图</small></span><input id="main-kv-reference-upload" type="file" accept="image/png,image/jpeg,image/webp" hidden></label>`:`<label class="btn btn-soft btn-sm kv-reference-upload">＋ 上传参考 KV<input id="main-kv-reference-upload" type="file" accept="image/png,image/jpeg,image/webp" hidden></label>`}<span class="field-hint">支持 PNG / JPEG / WebP，最大 6MB</span></div>`;return projectFormBase().replace('<div class="field full"><label>主 KV</label>',characterChoice+'<div class="field full"><label>主 KV</label>').replace('<button class="btn btn-primary btn-sm" data-action="generate-main-kv"',reference+'<button class="btn btn-primary btn-sm" data-action="generate-main-kv"');};
