const characterEditorBase=characterEditor;characterEditor=function(){const asset=activeCharacterAsset(),c=state.characterImage,tabs=`<div class="character-tabs">${state.characterImages.map(item=>{const status=item.imageState.status==='generating'?'生成中':item.imageState.confirmed?'已确认':item.imageState.image?'待确认':'待创建';return `<button class="character-tab ${item.id===asset.id?'active':''}" data-action="character-tab" data-id="${esc(item.id)}">${item.imageState.image?`<img src="${esc(item.imageState.views?.front?.image||item.imageState.image)}" alt="">`:'<span>✧</span>'}<b>${esc(item.label)}</b><small>${status}</small></button>`}).join('')}${state.characterImages.length<3?'<button class="character-tab-add" data-action="add-character-tab" title="添加主形象">＋</button>':''}</div>`,viewPanel=c.image?`<aside class="character-view-panel"><div><b>主形象多视图</b><small>${c.multiViewStatus==='ready'?'点击切换预览角度':c.sourceType==='upload'?'上传后点击生成三视图':'正在准备多视图'}</small></div><div class="character-view-list">${Object.entries(characterViewLabels).map(([key,label])=>{const view=c.views?.[key];return `<button class="character-view ${c.activeView===key?'active':''}" data-action="character-view" data-value="${key}" ${view?'':'disabled'}>${view?`<img src="${esc(view.image)}" alt="${label}">`:'<span>✧</span>'}<b>${label}</b></button>`}).join('')}</div>${c.sourceType==='upload'?`<div class="cutout-flow"><span class="cutout-status">${c.multiViewStatus==='generating'?(c.cutoutStatus==='processing'?'正在自动识别人物并抠图…':'正在生成三视图…'):c.multiViewStatus==='ready'?'三视图已完成':'点击后自动抠图并生成三视图'}</span><button class="btn btn-primary btn-sm" data-action="generate-character-views" ${characterBusy()?'disabled':''}>${c.multiViewStatus==='generating'?'处理中…':c.multiViewStatus==='ready'?'重新生成三视图':'生成三视图'}</button></div>`:''}</aside>`:'';let html=characterEditorBase().replace('<div class="character-layout">',tabs+'<div class="character-layout">').replace('<b>主形象预览</b>',`<b>${esc(asset.label)}预览 · ${characterViewLabels[c.activeView]||'正面'}</b>`).replace('确认主形象，进入画布 →','确认当前形象');if(c.image){html=html.replace('<div class="character-board','<div class="character-preview-grid"><div class="character-board').replace('</div><div class="character-source-actions">','</div>'+viewPanel+'</div><div class="character-source-actions">');}const canConfirm=c.image&&c.multiViewStatus==='ready'&&!characterBusy();html=html.replace('data-action="confirm-character"',`data-action="confirm-character" ${canConfirm&&!c.confirmed?'':'disabled'}`);const actions=`<div class="character-manager-actions">${asset.id!=='character'?'<button class="btn btn-quiet danger-action" data-action="delete-character-tab">删除当前形象</button>':'<span></span>'}<button class="btn btn-primary" data-action="finish-characters" ${confirmedCharacterAssets().length?'':'disabled'}>完成主形象设置，进入画布 →</button></div>`;html=html.replace('</section><aside class="character-chat-slot">',actions+'</section><aside class="character-chat-slot">').replace('AI 创意助手</span>',`AI 创意助手 · ${esc(asset.label)} · ${characterViewLabels[c.activeView]||'正面'}</span>`);return html;};
const characterNodeBase=characterNode;characterNode=function(){if(!usesMainCharacter())return '';const activeId=state.activeCharacterId,html=confirmedCharacterAssets().map((asset,index)=>{activateCharacter(asset.id,false);const pos=state.positions[asset.id]||{x:44,y:18+index*190};return characterNodeBase().replace(/data-node="character"/g,`data-node="${esc(asset.id)}"`).replace(/data-id="character"/g,`data-id="${esc(asset.id)}"`).replace('主要形象 · 3D',`${esc(asset.label)} · 3D`).replace(/style="left:[^"]+"/,`style="left:${pos.x}px;top:${pos.y}px"`);}).join('');activateCharacter(activeId,false);return html;};
const canvasNodeBase=canvasNode;canvasNode=function(scene,index){const html=canvasNodeBase(scene,index);return usesMainCharacter()?html:html.replace('<div class="thumb-person"></div>','<div class="scene-only-mark">▧</div>');};
const buildConnectionsBase=buildConnections;buildConnections=function(){if(!usesMainCharacter())return buildConnectionsBase().replace(/<path class="asset-link"[^>]*\/>/g,'');const first=state.characterImages[0],activeId=state.activeCharacterId;activateCharacter(first.id,false);let paths=buildConnectionsBase();for(const asset of confirmedCharacterAssets().slice(1)){const a=state.positions[asset.id]||{x:44,y:208};for(const link of state.links.filter(item=>item.startsWith(`${asset.id}:`))){const scene=state.scenes.find(item=>item.id===link.split(':')[1]);if(!scene)continue;const b=scenePosition(scene);paths+=`<path class="asset-link" d="M ${a.x+164} ${a.y+59} C ${a.x+210} ${a.y+59}, ${b.x-60} ${b.y-18}, ${b.x+90} ${b.y}"/>`;}}activateCharacter(activeId,false);return paths;};
const canvasBase=canvas;canvas=function(){const assets=confirmedCharacterAssets(),bar=usesMainCharacter()&&assets.length?`<div class="canvas-character-bar"><b>主形象资产</b>${assets.map(asset=>`<button class="canvas-character-chip ${state.selected===asset.id?'selected':''}" data-action="select-scene" data-id="${esc(asset.id)}"><img src="${esc(asset.imageState.views?.front?.image||asset.imageState.image)}" alt=""><span>${esc(asset.label)}</span></button>`).join('')}</div>`:'';return canvasBase().replace('<section class="canvas-shell',bar+'<section class="canvas-shell');};
