const renderGenerationActionsBase=render;render=function(){renderGenerationActionsBase();if(state.step===6)document.querySelectorAll('.generation-row').forEach((row,index)=>{const scene=state.scenes[index],actions=row.querySelector('.gen-state');if(scene?.generated&&actions&&!actions.querySelector('[data-action="preview-generated-scene"]')){actions.classList.add('gen-ready-actions');actions.insertAdjacentHTML('beforeend',`<button class="btn btn-soft btn-sm" data-action="preview-generated-scene" data-id="${esc(scene.id)}">▶ 预览</button><button class="btn btn-quiet btn-sm" data-action="edit-generated-scene" data-id="${esc(scene.id)}">编辑</button><button class="btn btn-soft btn-sm" data-action="regenerate-generated-scene" data-id="${esc(scene.id)}">↺ 重新生成</button>`);}});if(state.step===7){const oldButton=document.querySelector('.preview-monitor [data-action="open-export-modal"]');oldButton?.remove();const playerWrap=document.querySelector('.review-player-wrap');if(playerWrap&&!playerWrap.previousElementSibling?.matches('.preview-export-toolbar'))playerWrap.insertAdjacentHTML('beforebegin','<div class="preview-export-toolbar"><button class="btn btn-primary btn-sm" data-action="open-export-modal">导出</button></div>');const head=document.querySelector('.review-timeline-card .review-section-head');if(head&&!head.querySelector('[data-action="edit-preview-scene"]'))head.insertAdjacentHTML('beforeend',`<div class="review-timeline-actions"><span class="review-timeline-total">总时长 ${timeLabel(state.scenes.reduce((sum,s)=>sum+Number(s.duration||0),0))}</span><button class="btn btn-soft btn-sm" data-action="edit-preview-scene" data-id="${esc(state.previewSceneId||'')}">编辑</button></div>`);const next=document.querySelector('.review-footer [data-action="to-export"]');if(next)next.innerHTML='提交 VEEVA 审批 <span>→</span>';}if(state.step===8)document.querySelector('.step-title')?.replaceChildren(document.createTextNode('提交 VEEVA 审批'));};
