function creativeClock(seconds){const value=Math.round(Number(seconds)||0);return `${Math.floor(value/60)}:${String(value%60).padStart(2,'0')}`;}
function sceneScriptFields(s){return `<div class="creative-scene-fields"><div class="field"><label>分镜描述</label><textarea class="textarea" data-creative-field="description" data-id="${esc(s.id)}">${esc(s.description??'')}</textarea></div>${usesMainCharacter()?`<div class="field"><label>动作描述</label><textarea class="textarea" data-creative-field="actionDescription" data-id="${esc(s.id)}">${esc(s.actionDescription??s.description??'')}</textarea></div>`:''}<div class="field"><label>场景描述</label><textarea class="textarea" data-creative-field="sceneDescription" data-id="${esc(s.id)}">${esc(s.sceneDescription??s.description??'')}</textarea></div><div class="field creative-duration"><label>视频时长</label><div class="creative-time-stepper"><output aria-label="分镜起止时间" aria-live="polite">${esc(creativeTimeRange(s))}</output><div class="creative-time-buttons"><button type="button" data-action="adjust-creative-duration" data-id="${esc(s.id)}" data-value="1" title="增加 1 秒" aria-label="增加 1 秒" ${Number(s.duration)>=120?'disabled':''}>▴</button><button type="button" data-action="adjust-creative-duration" data-id="${esc(s.id)}" data-value="-1" title="减少 1 秒" aria-label="减少 1 秒" ${Number(s.duration)<=1?'disabled':''}>▾</button></div></div></div></div>`;}
function creativeSceneStart(scene){return state.scenes.slice(0,state.scenes.indexOf(scene)).reduce((total,item)=>total+Number(item.duration||0),0);}
function creativeTimeRange(scene){const start=creativeSceneStart(scene);return `${creativeClock(start)}-${creativeClock(start+Number(scene.duration||0))}`;}
function updateCreativeField(input){const scene=state.scenes.find(item=>item.id===input.dataset.id);if(!scene)return;const key=input.dataset.creativeField;if(key==='duration'||key==='timeRange'){let value=Number(input.value);if(key==='timeRange'){const match=input.value.trim().match(/^(\d+):([0-5]\d)\s*[-–]\s*(\d+):([0-5]\d)$/);if(!match){input.setCustomValidity?.('请输入起止时间，例如 0:00-0:13');return;}const start=Number(match[1])*60+Number(match[2]),end=Number(match[3])*60+Number(match[4]),expected=creativeSceneStart(scene);if(start!==expected||end<=start){input.setCustomValidity?.('开始时间应为 '+creativeClock(expected)+'，结束时间须晚于开始时间');return;}value=end-start;}input.setCustomValidity?.('');if(!Number.isFinite(value)||value<1||value>120)return;scene.duration=value;document.querySelectorAll('[data-creative-field="timeRange"]').forEach(field=>{if(field===input)return;const target=state.scenes.find(item=>item.id===field.dataset.id);if(target)field.value=creativeTimeRange(target);});scene.captionSegments?.forEach(segment=>{segment.startOffset=clamp(segment.startOffset,0,Math.max(0,value-.1));segment.endOffset=clamp(segment.endOffset,segment.startOffset+.1,value)});markVoiceStale(scene);}else{if(scene.sceneDescription===undefined)scene.sceneDescription=scene.description||'';if(scene.actionDescription===undefined)scene.actionDescription=scene.description||'';scene[key]=input.value;scene.prompt=[scene.description,usesMainCharacter()?scene.actionDescription:'',scene.sceneDescription].filter(Boolean).join('；');if(scene.keyframe)scene.keyframe.confirmed=false;}scene.generated=false;scene.status='待生成';invalidateAudioCheck('all');scheduleSave();}
async function demoCutoutImage(source){const image=new Image();await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=reject;image.src=source});const canvas=document.createElement('canvas');canvas.width=600;canvas.height=720;const context=canvas.getContext('2d');context.save();context.beginPath();context.ellipse(300,260,125,170,0,0,Math.PI*2);context.rect(220,350,160,160);context.ellipse(300,680,220,240,0,0,Math.PI*2);context.clip();context.drawImage(image,0,0,600,720);context.restore();return canvas.toDataURL('image/png');}
function generateUploadedViews(){const c=state.characterImage;if(!c.image||characterBusy())return;const token=++characterOperation,source=c.uploadOriginal||c.image;c.uploadOriginal=source;c.status='generating';c.error='';c.cutoutStatus='processing';c.multiViewStatus='generating';render();setTimeout(async()=>{if(token!==characterOperation||c!==state.characterImage)return;try{const front=await demoCutoutImage(source);if(token!==characterOperation||c!==state.characterImage)return;c.cutoutStatus='ready';render();setTimeout(()=>{if(token!==characterOperation||c!==state.characterImage)return;c.views={front:{image:front,source:front,selection:[],history:[],editPrompt:''}};for(const view of ['left','right','back']){const image=characterPortrait(view);c.views[view]={image,source:image,selection:[],history:[],editPrompt:''};}c.activeView='front';c.source=c.image=front;c.selection=[];c.history=[];c.cutoutConfirmed=true;c.multiViewStatus='ready';c.status='ready';invalidateCharacter();persist();render();toast('三视图已生成','success');},900);}catch{c.status='error';c.cutoutStatus='idle';c.multiViewStatus='idle';c.error='处理失败，请重新生成三视图';persist();render();}},800);}
const characterTransparentBase=characterEditor;characterEditor=function(){let html=characterTransparentBase();if(state.characterImage.multiViewStatus==='ready')html=html.replace('character-preview-grid','character-preview-grid transparent-views');return html;};

function updatePreviewRuler(){const ticks=[...document.querySelectorAll('.review-ruler span')];if(ticks.length!==state.scenes.length+2)return;let elapsed=0;ticks[0].textContent=timeLabel(0);state.scenes.forEach((scene,index)=>{elapsed+=Number(scene.duration||0);ticks[index+1].textContent=timeLabel(elapsed)});ticks[ticks.length-1].textContent=timeLabel(elapsed)}
const previewRenderBase=render;render=function(){if(state.step!==7&&reviewPlaybackTimer)stopReviewPlayback();previewRenderBase();if(state.step===6){const next=document.querySelector('.done-card+.page-actions [data-action="to-preview"]');if(next)next.textContent='进入视频预览 →';const hint=document.querySelector('.done-card .tiny.muted');if(hint)hint.textContent='进入视频预览，查看完整成片与分镜音轨。';}if(state.step===7){const total=state.scenes.reduce((sum,scene)=>sum+Number(scene.duration||0),0),progress=total?state.previewTime/total*100:0;document.querySelector('.review-player')?.classList.add(`ratio-${state.form.ratio.replace(':','-')}`);const time=document.querySelector('.monitor-time');if(time)time.textContent=`${timeLabel(state.previewTime)} / ${timeLabel(total)}`;const fill=document.querySelector('.monitor-track span');if(fill)fill.style.width=`${progress}%`;updatePreviewRuler();document.querySelectorAll('.review-audio-tools,.music-timeline,.qa-card,.chat-column').forEach(node=>node.remove());}if(state.step===8){const back=document.querySelector('[data-action="prev-step"]');if(back)back.textContent='← 返回视频预览';const rows=document.querySelectorAll('.export-preview .asset-row'),check=rows[rows.length-1];if(check){check.querySelector('.muted').textContent='预览状态';check.querySelector('b').textContent='可导出';}}};
const characterChoicesRenderBase=render;render=function(){characterChoicesRenderBase();if(state.step!==4||!usesMainCharacter()||state.characterImage.image||!state.characterImage.creationMode)return;const empty=document.querySelector('.character-empty');if(!empty||empty.querySelector('.character-create-actions'))return;const anchor=empty.querySelector('.character-ai-form,.character-upload-proxy');anchor?.insertAdjacentHTML('beforebegin',`<div class="character-create-actions"><button class="btn ${state.characterImage.creationMode==='upload'?'btn-primary':'btn-soft'}" data-action="open-character-upload">上传图片</button><button class="btn ${state.characterImage.creationMode==='ai'?'btn-primary':'btn-soft'}" data-action="show-character-ai">✦ AI 生成</button></div>`);};
const workflowRenderBase=render;render=function(){if(state.step===8||state.step===9){app.innerHTML=`<div class="app-shell">${header()}<main class="main">${stepper()}${state.step===8?feedbackPage():veevaSubmitPage()}</main></div>`;persist();return;}workflowRenderBase();if(state.step===7){const next=document.querySelector('.review-footer [data-action="to-export"]');if(next)next.innerHTML='进入意见收集 <span>→</span>';}};
render();
feedbackPage=function(){const f=state.feedback,manager=state.currentUser==='manager',total=state.scenes.reduce((sum,s)=>sum+Number(s.duration||0),0),active=state.scenes.find(s=>s.id===f.previewTarget),open=f.comments.filter(comment=>comment.status!=='resolved').length,canReview=manager&&['review','resubmitted'].includes(f.status),labels={draft:'尚未提交',review:'等待小王审阅',changes:'待小李修改',resubmitted:'等待小王复核',approved:'内部确认通过'};let cursor=0;const starts=Object.fromEntries(state.scenes.map(scene=>{const start=cursor;cursor+=Number(scene.duration||0);return [scene.id,start]})),time=active?starts[active.id]:clamp(f.previewTime,0,total),progress=total?time/total*100:0;return `${heading('STEP 09 · FEEDBACK','意见收集','小李和小王可不限轮次地提交、修改和复核意见。')}<section class="feedback-page"><div class="feedback-role-banner"><div><span class="pill ${manager?'pill-blue':'pill-green'}">${manager?'小王 · Line Manager':'小李 · 视频制作人'}</span><b>${labels[f.status]||labels.draft}</b><small>第 ${f.round} 轮审阅 · ${manager?'检查完整视频或定位具体分镜。':'处理意见后可再次提交小王复核。'}</small></div><span>${open} 条待处理意见</span></div><div class="feedback-layout"><section class="card feedback-video"><div class="feedback-video-art"><div class="preview-landscape"></div>${usesMainCharacter()?'<div class="character-person"></div>':''}<span class="feedback-preview-label">${active?`分镜 ${state.scenes.indexOf(active)+1} · ${esc(active.title)}`:'完整视频'}</span><button class="play-big" aria-label="播放视频">▶</button></div><div class="feedback-player-controls"><span>${timeLabel(time)} / ${timeLabel(total)}</span><div class="feedback-progress"><i style="width:${progress}%"></i></div><b>${active?`已跳转至 ${timeLabel(time)}`:'从头预览完整视频'}</b></div><div class="feedback-video-meta"><b>${esc(state.form.name||'未命名视频')}</b><span>${state.scenes.length} 个分镜 · ${total} 秒</span></div><div class="feedback-scenes"><button class="feedback-full-video ${!active?'selected':''}" data-action="select-feedback-preview" data-id="all"><span>▶</span><div><b>查看完整视频</b><small>从 00:00 开始播放全部内容</small></div></button>${state.scenes.map((s,i)=>`<article class="${active?.id===s.id?'selected':''}" data-action="select-feedback-preview" data-id="${esc(s.id)}"><span class="feedback-scene-thumb shot-${i%4}">${String(i+1).padStart(2,'0')}</span><div><b>${esc(s.title)}</b><p>${esc(s.description||'暂无分镜描述')}</p><small>${timeLabel(starts[s.id])}–${timeLabel(starts[s.id]+Number(s.duration||0))} · 字幕：${esc(activeCaptionText(s)||'暂无')}</small></div>${!manager&&f.comments.some(c=>c.target===s.id&&c.status!=='resolved')?`<button class="btn btn-soft btn-sm" data-action="edit-feedback-scene" data-id="${esc(s.id)}">去修改</button>`:''}</article>`).join('')}</div></section><aside class="card feedback-panel"><header><b>审阅意见</b><span>${f.comments.length} 条 · ${f.round} 轮</span></header>${canReview?`<div class="feedback-composer"><label>意见位置<select data-feedback-target><option value="all" ${f.target==='all'?'selected':''}>完整视频</option>${state.scenes.map((s,i)=>`<option value="${esc(s.id)}" ${f.target===s.id?'selected':''}>分镜 ${i+1} · ${esc(s.title)}</option>`).join('')}</select></label><textarea class="textarea" data-feedback-draft placeholder="描述需要修改的内容">${esc(f.draft||'')}</textarea><button class="btn btn-primary btn-sm" data-action="add-feedback-comment" ${f.draft.trim()?'':'disabled'}>添加意见</button></div>`:''}<div class="feedback-comments">${[...f.comments].reverse().map(comment=>{const scene=state.scenes.find(s=>s.id===comment.target),editing=manager&&canReview&&comment.round===f.round&&comment.status==='open'&&f.editingCommentId===comment.id;return `<article class="feedback-comment ${comment.status==='resolved'?'resolved':''}"><div><span>第 ${comment.round} 轮 · ${comment.target==='all'?'完整视频':esc(scene?.title||'分镜')}</span><time>${esc(comment.time||'')}</time></div>${editing?`<textarea class="textarea" data-feedback-edit-draft>${esc(f.editDraft)}</textarea><div class="feedback-comment-actions"><button class="btn btn-quiet btn-sm" data-action="cancel-feedback-edit">取消</button><button class="btn btn-primary btn-sm" data-action="save-feedback-comment" data-id="${esc(comment.id)}">保存</button></div>`:`<p>${esc(comment.text)}</p>`}${comment.reply?`<small>小李处理说明：${esc(comment.reply)}</small>`:''}${manager&&canReview&&comment.round===f.round&&comment.status==='open'&&!editing?`<div class="feedback-comment-actions"><button class="text-link" data-action="edit-feedback-comment" data-id="${esc(comment.id)}">编辑</button><button class="text-link danger-action" data-action="delete-feedback-comment" data-id="${esc(comment.id)}">删除</button></div>`:''}${!manager&&comment.status!=='resolved'?`<textarea class="textarea" data-feedback-reply="${esc(comment.id)}" placeholder="填写修改说明">${esc(comment.reply||'')}</textarea><button class="btn btn-soft btn-sm" data-action="resolve-feedback" data-id="${esc(comment.id)}" ${comment.reply?.trim()?'':'disabled'}>标记已修改</button>`:''}</article>`}).join('')||'<p class="feedback-empty">暂时没有审阅意见。</p>'}</div></aside></div><footer class="feedback-footer"><button class="btn btn-quiet" data-action="back-preview">← 返回视频预览</button><div>${!manager&&f.status==='draft'?'<button class="btn btn-primary" data-action="send-feedback-review">发送给小王审阅 →</button>':''}${canReview&&open?'<button class="btn btn-primary" data-action="submit-feedback-comments">提交修改意见</button>':''}${!manager&&f.status==='changes'?`<button class="btn btn-primary" data-action="resubmit-feedback" ${open?'disabled':''}>重新提交小王确认 →</button>`:''}${canReview&&!open?'<button class="btn btn-primary" data-action="approve-feedback">内部确认通过</button>':''}${!manager&&f.status==='approved'?'<button class="btn btn-primary" data-action="to-veeva">进入 VEEVA 提审 →</button>':''}</div></footer></section>`};if(state.step===8)render();
